    if(!isR){var nm0=stn(i),artEl=signEl.querySelector('.art'),mine=plate.k=(plate.k||0)+1,sd=STD[C.city]&&STD[C.city][nm0];
      var showPh=function(url,credit){var im=h('img');im.alt=nm0;im.onload=function(){if(mine!==plate.k||!artEl.isConnected)return;artEl.textContent='';artEl.classList.add('pho');artEl.style.backgroundImage='url("'+url+'")';artEl.style.backgroundSize='cover';artEl.style.backgroundPosition='center';artEl.style.backgroundRepeat='no-repeat';var cr=h('div','cr');cr.textContent=credit;artEl.parentNode.insertBefore(cr,artEl.nextSibling);};im.onerror=function(){if(sd&&url.indexOf('img/st/')>=0)runSearch();};im.src=url;};
      var runSearch=function(){stPhoto(nm0+' '+C.city,function(url){if(!url||mine!==plate.k||!artEl.isConnected)return;showPh(url,tx.photo);},nm0);};
      if(sd){var lmEl=signEl.querySelector('.lm'),tgEl=signEl.querySelector('.tg');if(sd[2]){lmEl.textContent='\uD83D\uDCCD '+sd[2];}else lmEl.style.display='none';tgEl.textContent=sd[3]==='i'?tx.idi:tx.fct;tgEl.className='tg '+(sd[3]==='i'?'i':'f');showPh(B+'img/st/'+sd[0]+'.jpg',tx.pho+sd[1]);}
      else{signEl.querySelector('.lm').style.display='none';signEl.querySelector('.tg').style.display='none';runSearch();}}
